import { loadFont as loadPlayfair } from "@remotion/google-fonts/PlayfairDisplay";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, spring, staticFile, useCurrentFrame, useVideoConfig } from "remotion";

// Esmero Crochê, vertical v2: o o diretor não quis a legenda presa na faixa de baixo. Agora cada frase tem
// uma montagem e um lugar: bloco vinho no meio da foto, inversão para o creme com a peça num círculo,
// cartão creme no alto, vinho com o logo, mosaico de fotos com faixas, foto que cresce para o "Adquira".
// Mesma locução e mesmos tempos da v1 (voz-v2 com a pausa encurtada, entrando em 0,2 s). Sem áudio aqui.

const { fontFamily: SERIF } = loadPlayfair("normal", { weights: ["700"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SERIF_I } = loadPlayfair("italic", { weights: ["500", "700"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SANS } = loadMontserrat("normal", { weights: ["500"], subsets: ["latin", "latin-ext"] });

export const HY2_FPS = 30;
export const HY2_FRAMES = Math.round(15.4 * HY2_FPS);
const WINE = "#892B57";
const CREAM = "#FAF3EB";
const INK = "#3B2A31";
const LOGO_RATIO = 1821 / 569;
const W = 1080;
const H = 1920;

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const IO = Easing.bezier(0.65, 0, 0.35, 1);
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const ease = (t: number, a: number, d: number, e = IO) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: e });
const lerp = (a: number, b: number, p: number) => a + (b - a) * p;

type Rect = { x: number; y: number; w: number; h: number };
const lerpRect = (a: Rect, b: Rect, p: number): Rect => ({ x: lerp(a.x, b.x, p), y: lerp(a.y, b.y, p), w: lerp(a.w, b.w, p), h: lerp(a.h, b.h, p) });

// marcos
const S2 = 0.8; // creme abre em círculo
const S3 = 3.12; // o círculo vira a foto inteira
const FLOOD = 5.45; // vinho cobre tudo
const DOORS = 6.72; // vinho abre como porta: mosaico
const GROW = 10.2; // uma foto do mosaico cresce
const END = 11.72; // cartão final

// ───────── peças ─────────
const Pic: React.FC<{ n: number; t: number; at: number; dur: number; zoom?: 1 | -1; clip?: string; pos?: string }> = ({ n, t, at, dur, zoom = 1, clip, pos = "50% 50%" }) => {
  const k = Math.max(0, Math.min(1, (t - at) / dur));
  const sc = zoom === -1 ? 1.1 - 0.08 * k : 1.0 + 0.08 * k;
  return (
    <div style={{ position: "absolute", inset: 0, overflow: "hidden", clipPath: clip }}>
      <Img src={staticFile(`hiury/foto-${n}.jpg`)} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: pos, transform: `scale(${sc})` }} />
    </div>
  );
};

const MaskWord: React.FC<{ t: number; at: number; children: string; size: number }> = ({ t, at, children, size }) => {
  const { fps } = useVideoConfig();
  const s = spring({ frame: Math.round((t - at + 0.05) * fps), fps, config: { damping: 200, stiffness: 140 } });
  return (
    <span style={{ display: "inline-block", overflow: "hidden", padding: `${size * 0.08}px 0 ${size * 0.18}px`, margin: `-${size * 0.08}px 0 -${size * 0.18}px`, verticalAlign: "top" }}>
      <span style={{ display: "inline-block", transform: `translateY(${(1 - s) * 115}%)` }}>{children}</span>
    </span>
  );
};

type Wd = [string, number];
const Words: React.FC<{ t: number; words: Wd[]; size: number; color: string; italic?: boolean; spacing?: number }> = ({ t, words, size, color, italic, spacing = 0.24 }) => (
  <div style={{ display: "flex", justifyContent: "center", whiteSpace: "nowrap", columnGap: size * spacing, fontFamily: italic ? SERIF_I : SERIF, fontStyle: italic ? "italic" : "normal", fontWeight: italic ? 500 : 700, fontSize: size, lineHeight: 1.08, color }}>
    {words.map(([w, at], i) => (
      <MaskWord key={i} t={t} at={at} size={size}>{w}</MaskWord>
    ))}
  </div>
);

// faixa de cor que entra varrendo de um lado; o texto sobe por máscara dentro dela
const Strip: React.FC<{ t: number; at: number; bg: string; from: "l" | "r" | "t"; out?: number; outTo?: "l" | "r"; pad?: string; children: React.ReactNode }> = ({ t, at, bg, from, out = 99, outTo = "r", pad = "14px 48px 18px", children }) => {
  const p = ease(t, at - 0.12, 0.42, OUT);
  const q = ease(t, out, 0.3, Easing.in(Easing.cubic));
  const r = (1 - p) * 100;
  const inClip = from === "l" ? `0 ${r}% 0 0` : from === "r" ? `0 0 0 ${r}%` : `0 0 ${r}% 0`;
  const clip = q > 0 ? (outTo === "r" ? `inset(0 0 0 ${q * 100}%)` : `inset(0 ${q * 100}% 0 0)`) : `inset(${inClip})`;
  return <div style={{ background: bg, padding: pad, clipPath: clip }}>{children}</div>;
};

const Thread: React.FC<{ t: number; at: number; color: string }> = ({ t, at, color }) => {
  const p = ease(t, at, 0.7);
  const L = 300;
  return (
    <svg width={240} height={28} viewBox="0 0 240 28" style={{ marginTop: 14, overflow: "visible" }}>
      <path d="M2 14 C 30 2, 50 26, 80 14 S 130 2, 160 14 S 210 26, 238 14" fill="none" stroke={color} strokeWidth={3} strokeLinecap="round" strokeDasharray={L} strokeDashoffset={L * (1 - p)} opacity={0.75} />
    </svg>
  );
};

const Logo: React.FC<{ width: number; color: string; reveal: number; style?: React.CSSProperties }> = ({ width, color, reveal, style }) => (
  <div style={{ width, height: width / LOGO_RATIO, background: color, WebkitMaskImage: `url(${staticFile("hiury/logo.png")})`, WebkitMaskSize: "contain", WebkitMaskRepeat: "no-repeat", WebkitMaskPosition: "center", clipPath: `inset(0 ${(1 - reveal) * 100}% 0 0)`, ...style }} />
);

// ───────── mosaico ─────────
// mosaico 2x3 de fotos 3:4, do maior tamanho que cabe na altura do formato
const tileRect = (i: number, hi: number): Rect => {
  const th = Math.min(600, (hi - 120) / 3);
  const tw = th * 0.75;
  const x0 = (W - (2 * tw + 20)) / 2;
  const y0 = (hi - (3 * th + 40)) / 2;
  return { x: x0 + (i % 2) * (tw + 20), y: y0 + Math.floor(i / 2) * (th + 20), w: tw, h: th };
};
const SET1 = [5, 13, 8, 14, 6, 1];
const SET2: (number | null)[] = [12, 4, 7, 9, null, null];
const GROW_TILE = 3;

const Tile: React.FC<{ t: number; i: number; r: Rect }> = ({ t, i, r }) => {
  const at = DOORS + 0.05 + i * 0.07;
  const p = ease(t, at, 0.5, OUT);
  const swap = 8.3 + i * 0.12;
  const n2 = SET2[i];
  return (
    <div style={{ position: "absolute", left: r.x, top: r.y, width: r.w, height: r.h, overflow: "hidden", borderRadius: 18, transform: `scale(${0.86 + 0.14 * p})`, opacity: Math.min(1, p * 2.5) }}>
      <Pic n={SET1[i]} t={t} at={at} dur={3} zoom={i % 2 ? -1 : 1} />
      {n2 && t > swap ? <Pic n={n2} t={t} at={swap} dur={2.5} zoom={i % 2 ? 1 : -1} clip={`inset(${(1 - ease(t, swap, 0.45)) * 100}% 0 0 0)`} /> : null}
    </div>
  );
};

export const HiuryV2: React.FC = () => {
  const t = useCurrentFrame() / HY2_FPS;
  // o desenho é feito com 1080 de largura; a altura acompanha o formato (1920 no 9:16, 1620 no 2:3)
  const { width: VW, height: VH } = useVideoConfig();
  const Hi = Math.round((W * VH) / VW);
  const k = Hi / H;
  const FULL: Rect = { x: 0, y: 0, w: W, h: Hi };
  const cr = Math.min(1, k + 0.1);

  // círculo da peça: nasce no creme, cresce e vira a foto inteira
  const circR = 330 * cr * spring({ frame: Math.round((t - 1.0) * HY2_FPS), fps: HY2_FPS, config: { damping: 18, stiffness: 120 } });
  const expand = ease(t, S3, 0.45);
  const R = lerp(circR, 1200 * Math.max(1, k), expand);
  const CY = Math.round(930 * k);

  // vinho: círculo saindo do cartão, depois porta abrindo
  const floodR = ease(t, FLOOD, 0.45) * 2300;
  const doors = ease(t, DOORS, 0.42);

  // foto que cresce do mosaico e depois encolhe no cartão
  const cardH = 800 - (H - Hi) * 0.5;
  const finalY = (Hi - (cardH + 569)) / 2;
  const card: Rect = { x: (W - cardH * 0.75) / 2, y: finalY, w: cardH * 0.75, h: cardH };
  const g = ease(t, GROW, 0.5);
  const m = ease(t, END, 0.6);
  const growRect = lerpRect(lerpRect(tileRect(GROW_TILE, Hi), FULL, g), card, m);

  const gridZoom = 1 + 0.05 * Math.max(0, Math.min(1, (t - DOORS) / 3.4));

  return (
    <AbsoluteFill style={{ background: CREAM }}>
      <div style={{ position: "absolute", left: 0, top: 0, width: W, height: Hi, transformOrigin: "0 0", transform: `scale(${VW / W})`, overflow: "hidden" }}>
      {/* 1 · abertura: detalhes em tela cheia + "Feito à mão," no bloco vinho */}
      {t < S2 + 0.45 ? (
        <AbsoluteFill>
          <Pic n={16} t={t} at={0} dur={0.5} />
          {t > 0.42 ? <Pic n={3} t={t} at={0.42} dur={0.6} zoom={-1} /> : null}
          <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
            <Strip t={t} at={0.18} bg={WINE} from="l" pad="26px 70px 34px">
              <Words t={t} size={190} color={CREAM} words={[["Feito", 0.2]]} />
              <Words t={t} size={150} color={CREAM} italic words={[["à", 0.46], ["mão,", 0.54]]} />
            </Strip>
          </AbsoluteFill>
        </AbsoluteFill>
      ) : null}

      {/* 2 · inversão: creme abre em círculo; "pontinho por pontinho" em vinho com a peça no meio */}
      {t >= S2 && t < FLOOD + 0.5 ? (
        <AbsoluteFill style={{ clipPath: `circle(${ease(t, S2, 0.4) * 1200}px at 540px ${Hi / 2}px)`, background: CREAM }}>
          {/* anel de pontos girando em volta da peça */}
          {t < S3 + 0.2 ? (
            <svg width={W} height={Hi} style={{ position: "absolute", inset: 0, opacity: 1 - ease(t, S3 - 0.1, 0.2, Easing.linear) }}>
              <circle cx={540} cy={CY} r={372 * cr} fill="none" stroke={WINE} strokeWidth={6} strokeLinecap="round" strokeDasharray="2 22" strokeDashoffset={-t * 18} pathLength={undefined} opacity={ease(t, 1.15, 0.6, Easing.linear)} transform={`rotate(${t * 12} 540 ${CY})`} />
            </svg>
          ) : null}
          <AbsoluteFill style={{ clipPath: `circle(${R}px at 540px ${lerp(CY, Hi / 2, expand)}px)` }}>
            <Pic n={10} t={t} at={1.0} dur={4.5} zoom={-1} />
            {t > 4.3 ? <Pic n={11} t={t} at={4.3} dur={1.6} clip={`inset(${(1 - ease(t, 4.3, 0.5)) * 100}% 0 0 0)`} /> : null}
          </AbsoluteFill>
          {t < S3 + 0.1 ? (
            <>
              <div style={{ position: "absolute", left: 0, right: 0, top: 230 * k, opacity: 1 - ease(t, S3 - 0.08, 0.1, Easing.linear) }}>
                <Words t={t} size={150} color={WINE} italic words={[["pontinho", 0.9]]} />
              </div>
              <div style={{ position: "absolute", left: 0, right: 0, top: 1420 * k, opacity: 1 - ease(t, S3 - 0.08, 0.1, Easing.linear) }}>
                <Words t={t} size={140} color={WINE} italic words={[["por", 2.2], ["pontinho", 2.56]]} />
              </div>
            </>
          ) : null}
          {/* 3 · cartão creme no alto: "especialmente para você" */}
          {t > 3.1 ? (
            <div style={{ position: "absolute", left: 0, right: 0, top: 230 * k, display: "flex", justifyContent: "center" }}>
              <Strip t={t} at={3.3} bg={CREAM} from="t" pad="34px 64px 30px">
                <Words t={t} size={104} color={WINE} italic words={[["especialmente", 3.28]]} />
                <Words t={t} size={150} color={WINE} words={[["para", 4.4], ["você", 4.92]]} />
              </Strip>
            </div>
          ) : null}
        </AbsoluteFill>
      ) : null}

      {/* 5 · mosaico (por baixo do vinho) */}
      {t >= DOORS - 0.05 && t < GROW + 0.55 ? (
        <AbsoluteFill style={{ transform: `scale(${gridZoom})` }}>
          {SET1.map((_, i) => (i === GROW_TILE ? null : <Tile key={i} t={t} i={i} r={tileRect(i, Hi)} />))}
          {t < GROW ? <Tile t={t} i={GROW_TILE} r={tileRect(GROW_TILE, Hi)} /> : null}
        </AbsoluteFill>
      ) : null}

      {/* 4 · vinho com o logo grande */}
      {t >= FLOOD && t < DOORS + 0.55 ? (
        <AbsoluteFill>
          {t < DOORS ? (
            <AbsoluteFill style={{ background: WINE, clipPath: `circle(${floodR}px at 540px ${440 * k}px)` }} />
          ) : (
            <>
              <div style={{ position: "absolute", left: 0, top: (-Hi / 2) * doors, width: W, height: Hi / 2, background: WINE }} />
              <div style={{ position: "absolute", left: 0, top: Hi / 2 + (Hi / 2) * doors, width: W, height: Hi / 2, background: WINE }} />
            </>
          )}
          <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", opacity: 1 - ease(t, DOORS - 0.08, 0.1, Easing.linear) }}>
            <Logo width={900} color={CREAM} reveal={ease(t, 5.8, 0.55, OUT)} style={{ transform: `scale(${0.94 + 0.06 * ease(t, 5.8, 0.6, OUT) + 0.03 * Math.max(0, t - 6.4)})` }} />
          </AbsoluteFill>
        </AbsoluteFill>
      ) : null}

      {/* faixas do mosaico */}
      {t > 7.0 && t < GROW + 0.4 ? (
        <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", gap: 16 }}>
          <Strip t={t} at={7.14} bg={CREAM} from="l" out={GROW} outTo="l">
            <Words t={t} size={120} color={WINE} words={[["Decoração", 7.12]]} />
          </Strip>
          <Strip t={t} at={8.36} bg={CREAM} from="r" out={GROW + 0.04} outTo="r">
            <Words t={t} size={120} color={WINE} words={[["e", 8.36], ["presentes", 8.8]]} />
          </Strip>
          <Strip t={t} at={9.2} bg={WINE} from="l" out={GROW + 0.08} outTo="l">
            <Words t={t} size={120} color={CREAM} italic words={[["com", 9.2], ["carinho", 9.54]]} />
          </Strip>
        </AbsoluteFill>
      ) : null}

      {/* 6 · foto do mosaico cresce: "Adquira já o seu!" */}
      {t >= GROW ? (
        <div style={{ position: "absolute", left: growRect.x, top: growRect.y, width: growRect.w, height: growRect.h, overflow: "hidden", borderRadius: lerp(18 * (1 - g), 28, m) }}>
          <Pic n={9} t={t} at={DOORS} dur={4.5} zoom={-1} />
          {t > 11.0 ? <Pic n={15} t={t} at={11.0} dur={4.4} zoom={-1} clip={`circle(${ease(t, 11.0, 0.5) * 75}% at 50% 50%)`} /> : null}
        </div>
      ) : null}
      {t >= GROW && t < END + 0.4 ? (
        <div style={{ position: "absolute", left: 0, right: 0, top: 420 * k, display: "flex", flexDirection: "column", alignItems: "center", gap: 0 }}>
          <Strip t={t} at={10.46} bg={CREAM} from="l" out={END} outTo="r" pad="18px 60px 24px">
            <Words t={t} size={200} color={WINE} words={[["Adquira", 10.46]]} />
          </Strip>
          <Strip t={t} at={11.16} bg={WINE} from="r" out={END + 0.04} outTo="r" pad="12px 56px 20px">
            <Words t={t} size={130} color={CREAM} italic words={[["já", 11.16], ["o", 11.26], ["seu!", 11.36]]} />
          </Strip>
        </div>
      ) : null}

      {/* 7 · final creme */}
      {t > END ? (
        <div style={{ position: "absolute", left: 0, top: finalY + cardH + 60, width: W, display: "flex", flexDirection: "column", alignItems: "center" }}>
          <Logo width={760} color={WINE} reveal={ease(t, 11.85, 0.6, OUT)} />
          <div style={{ marginTop: 54, fontFamily: SANS, fontWeight: 500, fontSize: 34, letterSpacing: "0.3em", color: INK, textTransform: "uppercase", overflow: "hidden", padding: "4px 0" }}>
            <MaskWord t={t} at={12.0} size={34}>{"Conheça nosso trabalho"}</MaskWord>
          </div>
          <div style={{ marginTop: 14, fontFamily: SERIF_I, fontStyle: "italic", fontWeight: 700, fontSize: 96, color: WINE, lineHeight: 1.1 }}>
            <MaskWord t={t} at={12.86} size={96}>{"@suamarca"}</MaskWord>
          </div>
          <Thread t={t} at={13.1} color={WINE} />
        </div>
      ) : null}
      </div>
    </AbsoluteFill>
  );
};

import React from "react";
import { Composition, registerRoot } from "remotion";
import { HY2_FPS, HY2_FRAMES, HiuryV2 } from "./HiuryV2";

const Root: React.FC = () => (
  <>
    <Composition id="HiuryVerticalV2x1440" component={HiuryV2} durationInFrames={HY2_FRAMES} fps={HY2_FPS} width={1440} height={2160} />
  </>
);
registerRoot(Root);
